/** 按 id 取单张邂逅案例 */
export function getXiehouCase(id: string): DecisionCase | undefined {
  return XIEHOU_CASES.find(c => c.id === id)
}

/** 按主题取邂逅案例子集（与 getCasesByTheme 互补，合并池见 xiaoshiKnowledge.ts） */
export function getXiehouCasesByTheme(theme: DecisionTheme): DecisionCase[] {
  return XIEHOU_CASES.filter(c => c.theme === theme)
}
